questions.question:
נתונה הפונקציה הבאה.
```c
int fun (int x, int y)
{
        if (y<0)
        {
                y = -y;
                x = -x;
        }
        if(y==1)
                return x;
        return fun(x,y-1)+x;
}
```
מה מחזירה הפונקציה? כתבו במחברת את התשובה המתאימה מהרשימה הבאה ונמקו את תשובתכם בקצרה:
a. סכום x ו-y
b. מכפלת x ו-y
c. x עם סימן הפוך
d. y עם סימן הפוך
e. אף אחת מהתשובות לעיל לא נכונה

questions.solution:
**פתרון רשמי** (19A-A עמ' 2):
```c
int isPalindromeRec(int *arr, int n)
{
      if (n <= 1)  // !!
            return 1;
      return arr[0] != arr[n - 1] ? 0 : isPalindromeRec(arr + 1, n - 2);
}
```
מקרה בסיס: מערך באורך 0 או 1 הוא פלינדרום. אחרת משווים את האיבר הראשון לאחרון, ואם הם שווים ממשיכים ברקורסיה על הקטע הפנימי (`arr + 1`, `n - 2`).

**פתרון רשמי** (19A-A עמ' 2-3):
```c
int is_permutation_of_palindrom(int *a, int n)
{
      int i, count = 0;
      int * temp = (int*)calloc(n, sizeof(int));
      for (i = 0; i<n; i++)
            temp[a[i]]++;
      for (i = 0; i < n; i++)
      {
            if (temp[i] % 2==1)
                  count++;
      }
      free(temp);
      return count<2;
}
```
אם מערך הוא פלינדרום, אז כל ערך מופיע מספר זוגי של פעמים, פרט למספר אחד שמופיע באמצע פלינדרום במקרה שהמערך הוא בגודל אי-זוגי. לכן כדי לבדוק האם מערך הוא תמורה של פלינדרום מספיק לספור כמות שערכים שמופיעים מספר אי-זוגי של פעמים. אם הכמות היא 0 או 1 המערך הוא תמורה של פלינדרום, אם הכמות גדולה מ-1 אין אפשרות לסדר את המערך כך שהוא יהיה פלינדרום.
הערה: אם יש רק ערך אחד שמופיע מספר אי-זוגי של פעמים, אז המערך אוטומטי בגודל אי-זוגי ואפשר להפוך אותו לפלינדרום. אם כל הערכים מופיעים מספר זוגי של פעמים, אז המערך הוא בגודל זוגי והוא תמורה של פלינדרום. לכן אין צורך לבדוק שני מקרים.

**פתרון רשמי** (19A-A עמ' 3):
```c
int bonus(int*a, int n)
{
      int i, count = 0;
      int * temp = (int*)calloc(n, sizeof(int));
      for (i = 0; i<n; i++)
            temp[a[i]]++;
      for (i = 0; i < n; i++)
      {
            if (temp[i] % 2)
                  count++;
      }
      free(temp);
      if (count > 1)
            return count - 1;
      else
            return 0;
}
```
ההערה הרשמית בפתרון: אם יש רק ערך אחד שמופיע מספר אי-זוגי של פעמים, המערך אוטומטי בגודל אי-זוגי ואפשר להפוך אותו לפלינדרום. אם כל הערכים מופיעים מספר זוגי של פעמים, המערך הוא בגודל זוגי והוא תמורה של פלינדרום. לכן אין צורך לבדוק שני מקרים.
הערת תמלול: בשאלה המודפסת כתוב "להוסיף 1 ו-5", אבל הפלינדרום המודפס `{1,1,4,3,4,1,1}` מתקבל מהוספת `4` ו-`1`.

**פתרון רשמי** (19A-A עמ' 3):
```c
int check_if_different_elements(int *a, int *b, int n)
{
   int ia=0, ib=n-1;

   while( ia < n  &&  ib >=0 )
{
        if (a[ia] == b[ib])
            return 0;
        if (a[ia] < b[ib])
            ia++;
        else
            ib--;
    }
     return 1;
}
```

הפתרון הרשמי עם תיקון שגיאת הקלדה: בחתימה המודפסת `is_sum (int* a, int* b, int n)` חסר הפרמטר `d` שהגוף משתמש בו, ולכן נוסף `int d` כפרמטר רביעי. שאר הקוד כפי שהודפס (19A-A עמ' 4).
```c
int is_sum (int* a, int* b, int n, int d)
{
  int i;
  merge_sort(b, 0, n-1);
  for(i=0; i<n; i++)
  {
    if(binary_search(b, n, d-a[i]) >=0 )
     return 1;
  }
  return 0;
}
```
ממיינים את `b` עם `merge_sort` בזמן $O(n\log n)$. לכל `a[i]` מחפשים ב-`b` הממוין את `d-a[i]` בחיפוש בינארי, $O(\log n)$ לכל חיפוש ו-$O(n\log n)$ לכל $n$ החיפושים. אם נמצא, אז `a[i]+b[j]==d` ומחזירים `1`.
סה"כ $O(n\log n)$.

הפתרון הרשמי עם תיקון שגיאת הקלדה: בלולאה הפנימית של בדיקת העמודות הודפס `for (i=0; i<N; j++)`, כך ש-`i` לא מתקדם והלולאה לא נעצרת; תוקן ל-`for (i=0; i<N; i++)`. שאר הקוד כפי שהודפס (19A-A עמ' 5).
```c
int CheckMagic(int A[N][N])
{
      int i, j, sum=0, curr_sum;
      //first row
      for (j=0; j<N; j++)
            sum += A[0][j];
      //check rows
      for (i=1; i<N; i++)
      {
            curr_sum = 0;
            for (j=0; j<N; j++)
                  curr_sum += A[i][j];
            if (curr_sum != sum)
                  return 0;
      }
      //check columns
      for (j=0; j<N; j++)
      {
            curr_sum = 0;
            for (i=0; i<N; i++)
                  curr_sum += A[i][j];
            if (curr_sum != sum)
                  return 0;
      }
      //check main diagonal
      curr_sum = 0;
      for (i=0; i<N; i++)
            curr_sum += A[i][i];
      if (curr_sum != sum)
            return 0;
      //check secondary diagonal
      curr_sum = 0;
      for (i=0; i<N; i++)
            curr_sum += A[i][N-i-1];
      if (curr_sum != sum)
            return 0;

      return 1;
}
```
מחשבים את סכום השורה הראשונה, ומשווים אליו את סכום כל שורה, כל עמודה ושני האלכסונים. בהפרש הראשון מחזירים `0`.
בדיקת השורות והעמודות עוברת על $N^2$ תאים כל אחת, והאלכסונים על $N$ תאים כל אחד: סה"כ $O(N^2)$.
